@Serializable data class OrderRequest(val id: String, val total: Long)   // published shape
@Serializable data class OrderAck(val orderId: String, val status: String)

routing {
    route("/v1/orders") {
        post {
            val req = call.receive<OrderRequest>()             // contract at the edge
            call.respond(OrderAck.from(orders.submit(req.toDomain())))
        }
    }
}
